import{z as s,x as o,o as r,c as d,q as A,j as n,D as B,d as a,s as i,S as l,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"跨品种做市","description":"","frontmatter":{"title":"跨品种做市","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/mm-crossproduct.md","filePath":"quant/mm-crossproduct.md","lastUpdated":1791063341000}'),F={name:"quant/mm-crossproduct.md"};function m(p,E,u,h,c,T){const t=o("Mermaid");return r(),d("div",null,[E[2]||(E[2]=A('<h1 id="跨品种做市" tabindex="-1">跨品种做市 <a class="header-anchor" href="#跨品种做市" aria-label="Permalink to &quot;跨品种做市&quot;">​</a></h1><div class="epigraph"><p>同一份风险在簿里有好几件外衣：ETF、成分股与期货；限额与偏度一旦按单品种设置，加起来的风险早就不是你以为的那份。</p><footer>—— 据 Guéant, Lehalle and Fernandez-Tapia, 2013 多资产一节；Harris, Trading and Exchanges, 2003 整理</footer></div><p><a href="/quant/mm-inventory-limits">上一课</a>把单品种的库存困境写成阶梯。但当簿里同时有 ETF、成分股篮子与股指期货，单品种的 \\(q\\) 与限额都要换成向量语言：偏度对净暴露、限额看协方差。<a href="/quant/glft-market-making">GLFT</a> 的多资产一节给出了惩罚矩阵化的原型。本课写业务口径：腿怎么组织、锚怎么联动、库存出口怎么分级。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一风险的多重表达：持有 ETF 约等于持有一篮子成分股，篮子又有期货表达。腿相关但不同时成交：ETF 先成交、篮子腿还在路上，间隙里的暴露不是零，而是带着单腿风险却没有单腿价差保护。错误形态两种：各腿独立设限额与偏度，名义限额加总后的真实风险远超预算——协方差既是余量也是错觉来源；各腿独立公允价，一腿成交后另一腿的锚没更新，两条偏度互相打架，报价在两个锚之间来回改。</p><p><span class="marginnote">直觉类比：单腿间隙像先拿到左脚鞋、右脚鞋还在送货路上——这段时间价格怎么走你全额承担，却收不到任何价差收入作补偿。腿间到达的几毫秒到几秒，是跨品种做市商真正的风险集中地。</span></p><h3 id="锚的联动" tabindex="-1">锚的联动 <a class="header-anchor" href="#锚的联动" aria-label="Permalink to &quot;锚的联动&quot;">​</a></h3><p>关联腿成交是公允价事件：ETF 腿吃掉一笔大单，篮子腿的锚要立即按冲击更新；期货跳一格，ETF 的折溢价与偏度基准同时移动。锚联动靠的是同一份定价服务而不是各腿独立实例，延迟预算按<a href="/quant/latency-budget">延迟预算</a>的口径分配——联动慢于对手的套利速度，你的窄价差就是别人的免费对冲。</p><p><span class="marginnote">把申赎出清当「免费平仓」是最贵的错觉：create/redeem 有过手费、最小申赎单位与篮子截止时间。尾盘残留的不足一个申赎单位的净头寸，只能按二级市场成本出清——预算必须按这个口径留。</span></p><p><span class="marginnote">数字实例：ETF 市价 100.05、篮子公允 100.00，折溢价 5 分。期货跳一格把篮子公允推到 100.03，真实折溢价只剩 2 分；若 ETF 腿的锚没联动，你仍按「5 分缓冲」挂窄价差，套利单会立刻吃走你按旧锚以为还有保护的那 3 分。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>风险单位用协方差折算：各腿库存进同一个惩罚矩阵，限额与偏度都对净数——这是 <a href="/quant/glft-market-making">GLFT</a> 多资产口径的直接应用。库存出口分级：盘内对冲腿最快；跨场所转移走<a href="/quant/smart-order-routing">智能订单路由</a>；申赎出清走 <a href="/quant/etf-create-redeem">ETF 实物申赎</a>，按过手费与最小申赎单位计价；期货基差仓作为隔夜表达，盯市现金流按<a href="/quant/futures-margin">期货保证金</a>口径预算。跨场所报价一致性：一个场所改价要在预算内同步到其余场所，否则被跨场所套利单打穿最薄的一处。</p>',12)),(r(),n(l,null,{default:B(()=>[i(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20ETF%5B%22ETF%20%E7%B0%BF%22%5D%20--%3E%20NET%5B%22%E5%87%80%E9%A3%8E%E9%99%A9%E7%9F%A9%E9%98%B5%EF%BC%9A%E5%8D%8F%E6%96%B9%E5%B7%AE%E6%8A%98%E7%AE%97%22%5D%0A%20%20BASKET%5B%22%E6%88%90%E5%88%86%E8%82%A1%20%2F%20%E7%AF%AE%E5%AD%90%E8%85%BF%22%5D%20--%3E%20NET%0A%20%20FUT%5B%22%E6%9C%9F%E8%B4%A7%E8%85%BF%22%5D%20--%3E%20NET%0A%20%20NET%20--%3E%20LIM%5B%22%E7%BB%9F%E4%B8%80%E9%99%90%E9%A2%9D%E4%B8%8E%E5%81%8F%E5%BA%A6%22%5D%0A%20%20LIM%20--%3E%20Q1%5B%22%E5%9C%BA%E6%89%80%20A%20%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20LIM%20--%3E%20Q2%5B%22%E5%9C%BA%E6%89%80%20B%20%E6%8A%A5%E4%BB%B7%22%5D%0A%20%20FILL%5B%22%E4%BB%BB%E4%B8%80%E8%85%BF%E6%88%90%E4%BA%A4%22%5D%20--%3E%7C%22%E6%9B%B4%E6%96%B0%E9%94%9A%E4%B8%8E%E5%81%8F%E5%BA%A6%22%7C%20NET%0A%20%20NET%20--%3E%20OUT%5B%22%E5%BA%93%E5%AD%98%E5%87%BA%E5%8F%A3%EF%BC%9A%E5%AF%B9%E5%86%B2%20%2F%20%E8%B7%AF%E7%94%B1%20%2F%20%E7%94%B3%E8%B5%8E%20%2F%20%E5%9F%BA%E5%B7%AE%E4%BB%93%22%5D%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("跨品种的收益来源三块：各腿的价差与回扣、两腿错价的均值回复（折溢价）、义务与费用结构在场所间的优化。错价收益的机制边界在 "),e("a",{href:"/quant/etf-arb"},"ETF 套利"),a("与"),e("a",{href:"/quant/index-arb"},"指数套利"),a("讲过：申赎机制保证折溢价收敛，做市商赚的是收敛路径上的价差服务费，不是方向。风险集中在「腿不同时」：间隙暴露等于无保护的单腿做市，所以腿间到达的时距分布本身是监控对象——篮子腿长时间挂不上，说明深度被别人先拿走了，此时 ETF 侧的报价宽度应当反映「对冲腿可得性」这个状态。")],-1)),(r(),n(l,null,{default:B(()=>[i(t,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20FILL%5B%22%E4%B8%80%E8%85%BF%E6%88%90%E4%BA%A4%EF%BC%8C%E5%8F%A6%E4%B8%80%E8%85%BF%E6%9C%AA%E8%B7%9F%E4%B8%8A%22%5D%20--%3E%20GAP%5B%22%E9%97%B4%E9%9A%99%E6%9A%B4%E9%9C%B2%EF%BC%9A%E6%97%A0%E4%BB%B7%E5%B7%AE%E4%BF%9D%E6%8A%A4%E7%9A%84%E5%8D%95%E8%85%BF%E9%A3%8E%E9%99%A9%22%5D%0A%20%20GAP%20--%3E%20E1%5B%22%E5%87%BA%E5%8F%A3%201%EF%BC%9A%E7%9B%98%E5%86%85%E5%AF%B9%E5%86%B2%E8%85%BF%EF%BC%8C%E6%9C%80%E5%BF%AB%22%5D%0A%20%20GAP%20--%3E%20E2%5B%22%E5%87%BA%E5%8F%A3%202%EF%BC%9A%E8%B7%A8%E5%9C%BA%E6%89%80%E6%99%BA%E8%83%BD%E8%B7%AF%E7%94%B1%22%5D%0A%20%20GAP%20--%3E%20E3%5B%22%E5%87%BA%E5%8F%A3%203%EF%BC%9A%E7%94%B3%E8%B5%8E%E5%87%BA%E6%B8%85%EF%BC%8C%E6%8C%89%E8%BF%87%E6%89%8B%E8%B4%B9%E4%B8%8E%E6%9C%80%E5%B0%8F%E7%94%B3%E8%B5%8E%E5%8D%95%E4%BD%8D%E8%AE%A1%E4%BB%B7%22%5D%0A%20%20GAP%20--%3E%20E4%5B%22%E5%87%BA%E5%8F%A3%204%EF%BC%9A%E6%9C%9F%E8%B4%A7%E5%9F%BA%E5%B7%AE%E4%BB%93%E4%BD%9C%E4%B8%BA%E9%9A%94%E5%A4%9C%E8%A1%A8%E8%BE%BE%22%5D%0A%20%20E3%20--%3E%20R%5B%22%E6%AE%8B%E7%95%99%E4%B8%8D%E8%B6%B3%E4%B8%80%E4%B8%AA%E7%94%B3%E8%B5%8E%E5%8D%95%E4%BD%8D%EF%BC%9A%E6%8C%89%E4%BA%8C%E7%BA%A7%E5%B8%82%E5%9C%BA%E6%88%90%E6%9C%AC%E8%AE%A1%E4%BB%B7%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=A('<p>相关断裂是向量限额的校核情景：常态下协方差给的限额余量，在相关性归一的当天消失，保证金价差优惠同时取消（期货保证金口径）。向量限额要按断裂情景重算一遍，留出余量。</p><p><span class="marginnote">常见误区：初学者容易把常态相关 0.99 当成可以放宽限额的余量——历史回看里两腿从没同时大跌过。相关断裂日（加息公告、指数调仓、期货到期），协方差优惠瞬间消失、保证金优惠同步取消，双腿同时要钱。向量限额要按「相关=1」的坏日子重算，而不是按月均相关过日子。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>结算与币种错配、交易时段错配（夜盘、假期日历）使「同时」这个假设打折；各场所的义务与费率不同，比较要费用调整后做，见 <a href="/quant/maker-taker">maker-taker</a>。跨品种做市不是套利课：折溢价的统计规律与申赎机制见 <a href="/quant/etf-create-redeem">ETF 实物申赎</a>与<a href="/quant/index-arb">指数套利</a>，本课只写做市侧的簿管理。商品与跨境品种的轮动与价差另有专门问题，见 <a href="/quant/intercommodity-spread">跨商品价差</a> 一类口径；不展开。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>同一风险的多重表达要求向量语言：限额看协方差，偏度对净暴露。</li><li>锚必须联动：任一腿成交与期货跳动都是公允价事件，联动慢了窄价差就是别人的对冲。</li><li>库存出口分级：对冲腿、跨场所路由、申赎出清、基差仓，各有标价。</li><li>间隙暴露是主要风险：腿间时距分布进监控，宽度反映对冲腿可得性。</li><li>向量限额按相关断裂情景校核，常态协方差给的余量在裂缝日消失。</li><li>出处：Guéant, Lehalle and Fernandez-Tapia, <em>Mathematics and Financial Economics</em>, 2013；Harris, <em>Trading and Exchanges</em>, 2003；Black, <em>Journal of Financial Economics</em>, 1976 的期现口径。</li></ul>',6))])}const D=s(F,[["render",m]]);export{C as __pageData,D as default};
